`timescale 1ns/1ps

// The vio_debug module is generated by scripts/create_debug_vio.tcl and is
// only elaborated when beam_ctrl_top.ENABLE_DEBUG_VIO is set to 1.
module debug_vio_bridge (
    input  logic        clk_i,
    input  logic [39:0] status_i,
    input  logic        ack_toggle_i,
    input  logic        adapter_error_i,
    output logic        frame_we_o,
    output logic [1:0]  frame_array_sel_o,
    output logic [2:0]  line_index_o,
    output logic [1:0]  chip_index_o,
    output logic [23:0] frame_data_o,
    output logic        submit_toggle_o,
    output logic [1:0]  cmd_array_sel_o,
    output logic [7:0]  cmd_line_mask_o,
    output logic        cmd_write_o,
    output logic        cmd_load_o,
    output logic        clear_status_o
);

    vio_debug u_vio (
        .clk(clk_i),
        .probe_in0(status_i),
        .probe_in1(ack_toggle_i),
        .probe_in2(adapter_error_i),
        .probe_out0(frame_we_o),
        .probe_out1(frame_array_sel_o),
        .probe_out2(line_index_o),
        .probe_out3(chip_index_o),
        .probe_out4(frame_data_o),
        .probe_out5(submit_toggle_o),
        .probe_out6(cmd_array_sel_o),
        .probe_out7(cmd_line_mask_o),
        .probe_out8(cmd_write_o),
        .probe_out9(cmd_load_o),
        .probe_out10(clear_status_o)
    );

endmodule
